package org.jsoup.parser;

import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

import java.util.stream.Stream;

import static org.junit.jupiter.api.Assertions.assertEquals;

/**
 * Verifies {@link TokenQueue#escapeCssIdentifier(String)} against the CSSOM
 * "serialize an identifier" algorithm (https://www.w3.org/TR/cssom-1/#serialize-an-identifier).
 *
 * <p>Each test case is a pair {@code (expected, input)}: the {@code input} identifier is escaped
 * and compared to the {@code expected} serialized form. Non-printable and special characters are
 * written as {@code \\uXXXX} unicode escapes so the exact code points under test stay explicit.</p>
 */
public class TokenQueueTest_escapeCssIdentifier {

    /**
     * Cases ported from the Web Platform Tests for {@code CSS.escape}.
     * Source: https://github.com/web-platform-tests/wpt/blob/328fa1c67bf5dfa6f24571d4c41dd10224b6d247/css/cssom/escape.html
     */
    private static Stream<Arguments> webPlatformCases() {
        return Stream.of(
            // Empty input is returned unchanged
            Arguments.of("", ""),

            // NULL bytes (U+0000) become the replacement character (U+FFFD)
            Arguments.of("�", "�"),
            Arguments.of("a�", "a�"),
            Arguments.of("�b", "�b"),
            Arguments.of("a�b", "a�b"),

            // Existing replacement characters (U+FFFD) are preserved
            Arguments.of("�", "�"),
            Arguments.of("a�", "a�"),
            Arguments.of("�b", "�b"),
            Arguments.of("a�b", "a�b"),

            // A leading digit is escaped as a code point
            Arguments.of("\\30 a", "0a"),
            Arguments.of("\\31 a", "1a"),
            Arguments.of("\\32 a", "2a"),
            Arguments.of("\\33 a", "3a"),
            Arguments.of("\\34 a", "4a"),
            Arguments.of("\\35 a", "5a"),
            Arguments.of("\\36 a", "6a"),
            Arguments.of("\\37 a", "7a"),
            Arguments.of("\\38 a", "8a"),
            Arguments.of("\\39 a", "9a"),

            // A digit that is not the first character is left as-is
            Arguments.of("a0b", "a0b"),
            Arguments.of("a1b", "a1b"),
            Arguments.of("a2b", "a2b"),
            Arguments.of("a3b", "a3b"),
            Arguments.of("a4b", "a4b"),
            Arguments.of("a5b", "a5b"),
            Arguments.of("a6b", "a6b"),
            Arguments.of("a7b", "a7b"),
            Arguments.of("a8b", "a8b"),
            Arguments.of("a9b", "a9b"),

            // A digit following a leading dash is escaped as a code point
            Arguments.of("-\\30 a", "-0a"),
            Arguments.of("-\\31 a", "-1a"),
            Arguments.of("-\\32 a", "-2a"),
            Arguments.of("-\\33 a", "-3a"),
            Arguments.of("-\\34 a", "-4a"),
            Arguments.of("-\\35 a", "-5a"),
            Arguments.of("-\\36 a", "-6a"),
            Arguments.of("-\\37 a", "-7a"),
            Arguments.of("-\\38 a", "-8a"),
            Arguments.of("-\\39 a", "-9a"),

            // A leading double dash needs no escaping
            Arguments.of("--a", "--a"),

            // Low control characters (U+0001..U+001F) are escaped as code points
            Arguments.of("\\1 \\2 \\1e \\1f ", ""),

            // "-" (U+002D), "_" (U+005F), and code points >= U+0080 are left as-is
            Arguments.of("-_©", "-_©"),

            // U+007F is escaped as a code point; U+0080..U+009F are left as-is
            Arguments.of(
                "\\7f ",
                ""),
            Arguments.of(" ¡¢", " ¡¢"),
            Arguments.of("a0123456789b", "a0123456789b"),
            Arguments.of("abcdefghijklmnopqrstuvwxyz", "abcdefghijklmnopqrstuvwxyz"),
            Arguments.of("ABCDEFGHIJKLMNOPQRSTUVWXYZ", "ABCDEFGHIJKLMNOPQRSTUVWXYZ"),

            // Backslashes are backslash-escaped
            Arguments.of("hello\\\\world", "hello\\world"),

            // A BMP code point >= U+0080 is preserved as-is
            Arguments.of("helloሴworld", "helloሴworld"),

            // A lone dash and a leading space/bang are backslash-escaped
            Arguments.of("\\-", "-"),
            Arguments.of("\\ \\!xy", " !xy"),

            // Astral symbol (U+1D306 TETRAGRAM FOR CENTRE) is preserved
            Arguments.of("𝌆", "𝌆"),

            // Lone surrogates are preserved
            Arguments.of("\uDF06", "\uDF06"),
            Arguments.of("\uD834", "\uD834"));
    }

    /** Extra jsoup-specific cases beyond the Web Platform Test suite. */
    private static Stream<Arguments> additionalCases() {
        return Stream.of(
            Arguments.of("one\\#two\\.three\\/four\\\\five", "one#two.three/four\\five"),
            Arguments.of("-a", "-a"),
            Arguments.of("--", "--"));
    }

    @ParameterizedTest
    @MethodSource("webPlatformCases")
    @MethodSource("additionalCases")
    public void escapeCssIdentifier(String expected, String input) {
        assertEquals(expected, TokenQueue.escapeCssIdentifier(input));
    }
}
